import { readFileSync, writeFileSync } from 'node:fs';

const read = (path) => readFileSync(path, 'utf8');
const write = (path, content) => writeFileSync(path, content);
const replaceOnce = (content, search, replacement, label) => {
  if (!content.includes(search)) throw new Error(`Trecho não encontrado: ${label}`);
  return content.replace(search, replacement);
};
const replaceRegex = (content, regex, replacement, label) => {
  if (!regex.test(content)) throw new Error(`Padrão não encontrado: ${label}`);
  regex.lastIndex = 0;
  return content.replace(regex, replacement);
};

// 1) Versão.
{
  const path = 'package.json';
  const pkg = JSON.parse(read(path));
  pkg.version = '1.0.46';
  write(path, `${JSON.stringify(pkg, null, 2)}\n`);
}

// 2) Runtime estrutural: a semântica de defesa só pertence à tabela pública;
// calendário passa a ser síncrono e deixa de buscar /api/processes para decorar o DOM.
{
  const path = 'src/components/PortalStructuralRuntime.tsx';
  let source = read(path);
  source = source.replace("let calendarProcesses: any[] | null = null;\nlet calendarFetch: Promise<any[]> | null = null;\n", '');
  source = replaceOnce(
    source,
    "function normalizeDefenseRows(table: HTMLTableElement) {\n  const headers = Array.from(table.tHead?.rows[0]?.cells || []) as HTMLTableCellElement[];",
    "function normalizeDefenseRows(table: HTMLTableElement) {\n  // Estado temporal (defendida / futura) é exclusivo da planilha pública de defesas.\n  // Não classifique Meus TCCs, Presidência ou outras planilhas por data, pois nesses\n  // contextos a cor do processo representa vínculo ou assinatura.\n  if (!table.closest('#formal-monthly-calendar-section')) return;\n  const headers = Array.from(table.tHead?.rows[0]?.cells || []) as HTMLTableCellElement[];",
    'escopo temporal das pílulas',
  );
  source = replaceRegex(
    source,
    /function dateKey\(value: string\) \{[\s\S]*?\nfunction enhanceAll\(\) \{/,
    `function enhanceCalendar() {\n  const period = calendarPeriod();\n  const firstCell = document.querySelector<HTMLElement>('.portal-calendar-day-cell');\n  const grid = firstCell?.parentElement;\n  if (!period || !grid) return;\n  grid.classList.add('portal-core-calendar-grid');\n  const daysHeader = grid.parentElement?.previousElementSibling as HTMLElement | null;\n  daysHeader?.classList.add('portal-core-calendar-week-header');\n  if (!grid.isConnected) return;\n\n  grid.querySelectorAll<HTMLElement>('.portal-calendar-day-cell').forEach((cell) => {\n    const day = Number(cell.querySelector(':scope > div:first-child span')?.textContent?.trim() || cell.querySelector('span')?.textContent?.trim());\n    if (!day) return;\n    const weekday = new Date(period.year, period.month, day).getDay();\n    const weekend = weekday === 0 || weekday === 6;\n    cell.classList.toggle('portal-core-calendar-weekend', weekend);\n    cell.setAttribute('aria-disabled', weekend ? 'true' : 'false');\n    if (!cell.dataset.portalCoreWeekendGuard) {\n      cell.dataset.portalCoreWeekendGuard = 'true';\n      cell.addEventListener('click', (event) => {\n        if (!cell.classList.contains('portal-core-calendar-weekend')) return;\n        event.preventDefault();\n        event.stopPropagation();\n      }, true);\n    }\n    // Remove somente artefatos de versões anteriores do runtime; filhos React permanecem intactos.\n    cell.querySelector('.portal-core-calendar-previews')?.remove();\n  });\n}\n\nfunction enhanceAll() {`,
    'runtime assíncrono do calendário',
  );
  source = source.replace('  void enhanceCalendar();', '  enhanceCalendar();');
  write(path, source);
}

// 3) Calendário React: fim de semana é estado nativo e imediato; clique de dia útil
// usa os dados já carregados pela página, sem depender do enhancer estrutural.
{
  const path = 'src/pages/HomePage.tsx';
  let source = read(path);
  source = replaceOnce(
    source,
    "                const colIndex = cellIndex % 7;\n                const isTopHalf = rowIndex <= 2;",
    "                const colIndex = cellIndex % 7;\n                const isWeekend = colIndex === 0 || colIndex === 6;\n                const isTopHalf = rowIndex <= 2;",
    'cálculo imediato de fim de semana',
  );
  source = replaceOnce(
    source,
    "                    onClick={() => {\n                      if (hasEvents) {\n                        setSelectedDayDefenses(dayDefenses.length > 0 ? dayDefenses : null);\n                        setSelectedDayGcalEvents(dayGcal.length > 0 ? dayGcal : null);\n                      }\n                    }}",
    "                    onClick={() => {\n                      if (hasEvents && !isWeekend) {\n                        setSelectedDayDefenses(dayDefenses.length > 0 ? dayDefenses : null);\n                        setSelectedDayGcalEvents(dayGcal.length > 0 ? dayGcal : null);\n                      }\n                    }}\n                    aria-disabled={isWeekend ? true : undefined}",
    'clique do calendário',
  );
  source = replaceOnce(
    source,
    "                      hasEvents\n                        ? isPastDay\n                          ? 'bg-slate-100/90 hover:bg-slate-200/80 border-slate-300 cursor-pointer h-16 sm:h-20 shadow-2xs text-slate-500 active:scale-[0.98]'\n                          : 'bg-slate-100/80 hover:bg-slate-200/90 border-slate-300 cursor-pointer h-16 sm:h-20 shadow-2xs active:scale-[0.98]'\n                        : 'bg-white hover:bg-slate-50 border-slate-200 cursor-default h-16 sm:h-20'",
    "                      isWeekend\n                        ? 'portal-core-calendar-weekend bg-slate-100/75 border-slate-200 cursor-default h-16 sm:h-20 text-slate-400'\n                        : hasEvents\n                          ? 'bg-slate-100/80 border-slate-300 cursor-pointer h-16 sm:h-20 shadow-2xs active:scale-[0.98]'\n                          : 'bg-white border-slate-200 cursor-default h-16 sm:h-20'",
    'paleta dos dias do calendário',
  );
  source = replaceOnce(
    source,
    "                    title={hasEvents ? `Clique para abrir as ${totalEvents} defesas do dia ${dayNum}` : undefined}",
    "                    title={isWeekend ? 'Fim de semana — indisponível para defesas' : hasEvents ? `Clique para abrir as ${totalEvents} defesas do dia ${dayNum}` : undefined}",
    'título acessível do calendário',
  );
  source = replaceOnce(
    source,
    "                          className={`transition-all duration-200 ${\n                            isPast\n                              ? 'bg-slate-100/40 text-slate-400 opacity-60'\n                              : `${defStyles.rowZebraClass} hover:bg-slate-100/60 ${defStyles.cellTextColorClass}`\n                          }`}",
    "                          className={`transition-all duration-200 ${defStyles.rowZebraClass} ${defStyles.cellTextColorClass}`}",
    'linhas passadas sem fosqueamento',
  );
  write(path, source);
}

// 4) Texto tabular sempre preto por contrato. As cores semânticas ficam reservadas
// a pílulas, estados e ações, não ao conteúdo comum das células.
{
  const path = 'src/utils/tableFormatters.ts';
  let source = read(path);
  source = replaceRegex(
    source,
    /  \/\/ Cell Text Color\n  let cellTextColorClass = 'text-slate-900';[\s\S]*?\n\n  \/\/ Column Borders & Zebra Striping/,
    `  // Cell Text Color — contrato global 1.0.46: conteúdo tabular comum é preto.\n  // Status, filtros e pílulas possuem seus próprios tokens semânticos.\n  const cellTextColorClass = 'text-black';\n\n  // Column Borders & Zebra Striping`,
    'cor global das células',
  );
  write(path, source);
}

// 5) Meus TCCs: filtro e botão de processo usam exatamente a mesma fonte semântica.
{
  const path = 'src/pages/MeusProcessosPage.tsx';
  let source = read(path);
  source = replaceOnce(
    source,
    "                  const chip = getFilterChipProps(catKey.toLowerCase(), isSelected, meusProcessosTextFormat, cfg.label);\n\n                  return (",
    "                  return (",
    'remoção da segunda fonte de cores dos filtros',
  );
  source = replaceOnce(
    source,
    "                      style={chip.buttonStyle}",
    "                      style={{ backgroundColor: cfg.bgColor, color: cfg.textHex, borderColor: cfg.borderColor, opacity: isSelected ? 1 : 0.62, boxShadow: isSelected ? `inset 0 0 0 1px ${cfg.borderColor}` : 'none' }}",
    'filtro com cor do vínculo',
  );
  source = source.replace('title={`Clique para ${isSelected ? \'isolar ou alternar\' : \'exibir\'} TCCs com papel de ${chip.label}`}', 'title={`Clique para ${isSelected ? \'isolar ou alternar\' : \'exibir\'} TCCs com papel de ${cfg.label}`}');
  source = source.replace('style={{ backgroundColor: chip.dotColor }}', 'style={{ backgroundColor: cfg.borderColor }}');
  source = source.replace('<span className="whitespace-nowrap font-extrabold">{chip.label}</span>', '<span className="whitespace-nowrap font-extrabold">{cfg.label}</span>');
  source = source.replace('style={chip.badgeStyle}', 'style={{ backgroundColor: cfg.borderColor, color: \'#ffffff\' }}');
  source = replaceOnce(
    source,
    "                  className={styles.firstColBtnClass}\n                  style={{ backgroundColor: roleConfig.bgColor, borderColor: roleConfig.borderColor, color: roleConfig.textHex }}",
    "                  className={`${styles.firstColBtnClass} portal-role-process-button`}\n                  style={{ '--portal-role-bg': roleConfig.bgColor, '--portal-role-border': roleConfig.borderColor, '--portal-role-text': roleConfig.textHex } as React.CSSProperties}",
    'botão de processo por vínculo',
  );
  write(path, source);
}

// 6) Presidência: concluído/assinado é verde mesmo quando não há job Asten atual;
// filtros usam os mesmos tokens das pílulas.
{
  const path = 'src/pages/CoordenadorPage.tsx';
  let source = read(path);
  source = replaceOnce(
    source,
    "        const status = getDeclarationStatus(proc.id);\n        const signed = status.label === 'Assinada';\n        const tone = signed ? PORTAL_SEMANTIC_COLORS.signature.signed : PORTAL_SEMANTIC_COLORS.signature.pending;",
    "        const job = getDeclarationJob(proc.id);\n        const signed = proc.status === 'CONCLUIDO' || Boolean(job && ['SIGNED', 'DRIVE_SYNC_PENDING', 'ARCHIVED'].includes(job.status));\n        const tone = signed ? PORTAL_SEMANTIC_COLORS.signature.signed : PORTAL_SEMANTIC_COLORS.signature.pending;",
    'semântica de assinatura da Presidência',
  );
  source = replaceOnce(
    source,
    "              {normalizeProcessNumber(proc.protocolo || proc.id)}\n            </span>",
    "              {normalizeProcessNumber(proc.protocolo || proc.id)}\n            </span>",
    'pílula de presidência preservada',
  );
  source = replaceOnce(
    source,
    "                    const chip = getFilterChipProps(filter.key, isSelected, coordTextFormat, filter.label);",
    "                    const semanticTone = filter.key === 'assinadas' ? PORTAL_SEMANTIC_COLORS.signature.signed : PORTAL_SEMANTIC_COLORS.signature.pending;\n                    const chip = getFilterChipProps(filter.key, isSelected, coordTextFormat, filter.label);\n                    const chipButtonStyle = { backgroundColor: semanticTone.bg, color: semanticTone.text, borderColor: semanticTone.border, opacity: isSelected ? 1 : 0.62, boxShadow: isSelected ? `inset 0 0 0 1px ${semanticTone.border}` : 'none' };\n                    const chipBadgeStyle = { backgroundColor: semanticTone.border, color: '#ffffff' };",
    'tokens dos filtros da Presidência',
  );
  // No bloco de abas, substitui apenas as referências imediatamente posteriores.
  const filterStart = source.indexOf("const semanticTone = filter.key === 'assinadas'");
  if (filterStart < 0) throw new Error('Bloco de filtros da Presidência não encontrado');
  const filterEnd = source.indexOf('                  })}', filterStart);
  if (filterEnd < 0) throw new Error('Fim do bloco de filtros da Presidência não encontrado');
  let filterBlock = source.slice(filterStart, filterEnd);
  filterBlock = filterBlock.replace('style={chip.buttonStyle}', 'style={chipButtonStyle}').replace('style={chip.badgeStyle}', 'style={chipBadgeStyle}');
  source = source.slice(0, filterStart) + filterBlock + source.slice(filterEnd);
  write(path, source);
}

// 7) Indicadores: reconcilia contrato backend/frontend e adiciona estatística temporal.
write('server/publicIndicators.ts', `import type { ProcessData } from '../src/types';\n\nexport type PublicIndicatorBucket = { label: string; count: number; key?: string };\nexport type PublicIndicatorsPayload = {\n  generatedAt: string;\n  privacy: { containsPersonalData: false; smallGroupSuppressed: boolean; minimumGroupSize: number; minimumBucketSize: number };\n  totals: { registered: number; completed: number; published: number; defended: number; inProgress: number; completionRate: number; publicationRate: number; coauthorRate: number };\n  descriptive: null | { monthlyMean: number; monthlyMedian: number; monthlyStdDev: number; peakMonth: string | null; peakMonthCount: number; completionDaysMean: number; completionDaysMedian: number; observedMonths: number };\n  byStatus: Array<{ key: string; label: string; count: number }>;\n  years: PublicIndicatorBucket[]; months: PublicIndicatorBucket[]; themes: PublicIndicatorBucket[]; workTypes: PublicIndicatorBucket[];\n  locations: PublicIndicatorBucket[]; outcomes: PublicIndicatorBucket[]; formats: PublicIndicatorBucket[]; weekdays: PublicIndicatorBucket[]; dayparts: PublicIndicatorBucket[];\n};\n\nconst MIN_PUBLIC_GROUP_SIZE = 5;\nconst MIN_PUBLIC_BUCKET_SIZE = 3;\nconst TIME_ZONE = 'America/Sao_Paulo';\nconst STATUS_LABELS: Record<string,string> = {\n  EM_RASCUNHO:'Em rascunho', AGUARDANDO_CONFIRMACAO_LOCAL:'Confirmando local', AGUARDANDO_DEFESA:'Aguardando defesa',\n  EM_AVALIACAO:'Em avaliação', AGUARDANDO_DADOS_FINAIS:'Dados finais', AGUARDANDO_ASSINATURA:'Assinaturas', CONCLUIDO:'Concluído'\n};\nconst WORK_TYPE_LABELS: Record<string,string> = { MONOGRAFIA:'Monografia', ARTIGO:'Artigo', OUTRO:'Outro', 'NÃO INFORMADO':'Não informado' };\nconst clean = (value:string) => String(value || '').normalize('NFKC').replace(/\\s+/g,' ').trim();\nconst countBy = (values:string[]) => Object.entries(values.reduce<Record<string,number>>((acc,value)=>{ if(value) acc[value]=(acc[value]||0)+1; return acc; },{})).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'pt-BR'));\nconst buckets = (values:string[], limit?:number) => (limit ? countBy(values).slice(0,limit) : countBy(values)).map(([label,count])=>({label,count}));\nconst publicBuckets = (items:PublicIndicatorBucket[]) => items.filter(item=>item.count>=MIN_PUBLIC_BUCKET_SIZE);\nconst round1 = (value:number) => Number(value.toFixed(1));\nconst mean = (values:number[]) => values.length ? values.reduce((sum,value)=>sum+value,0)/values.length : 0;\nconst median = (values:number[]) => { if(!values.length)return 0; const sorted=[...values].sort((a,b)=>a-b); const mid=Math.floor(sorted.length/2); return sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2; };\nconst stddev = (values:number[]) => { if(!values.length)return 0; const avg=mean(values); return Math.sqrt(mean(values.map(value=>(value-avg)**2))); };\nconst datePart = (iso:string, options:Intl.DateTimeFormatOptions) => { try { return new Intl.DateTimeFormat('pt-BR',{timeZone:TIME_ZONE,...options}).format(new Date(iso)); } catch { return ''; } };\n\nexport function buildPublicIndicators(processes: ProcessData[], now = Date.now()): PublicIndicatorsPayload {\n  const safe = Array.isArray(processes) ? processes : [];\n  const total = safe.length;\n  const smallGroupSuppressed = total > 0 && total < MIN_PUBLIC_GROUP_SIZE;\n  const completedItems = safe.filter(p=>p.status==='CONCLUIDO');\n  const completed = completedItems.length;\n  const published = safe.filter(p=>p.acervo?.publicationState==='PUBLIC' || (p.acervo?.isPublic && Boolean(p.acervo?.publicFullWorkFileId || p.acervo?.publicExpandedAbstractFileId))).length;\n  const defendedItems = safe.filter(p=>Boolean(p.defesa?.startAt) && new Date(p.defesa.startAt).getTime()<=now);\n  const defended = defendedItems.length;\n  const coauthors = safe.filter(p=>Boolean(p.aluno2)).length;\n\n  const rawByStatus = Object.entries(safe.reduce<Record<string,number>>((acc,p)=>{acc[p.status]=(acc[p.status]||0)+1;return acc;},{})).map(([key,count])=>({key,label:STATUS_LABELS[key]||key,count})).sort((a,b)=>b.count-a.count);\n  const rawYears = buckets(defendedItems.map(p=>datePart(p.defesa.startAt,{year:'numeric'}))).sort((a,b)=>a.label.localeCompare(b.label));\n  const rawMonths = buckets(defendedItems.map(p=>{try{const d=new Date(p.defesa.startAt);const parts=new Intl.DateTimeFormat('en-CA',{timeZone:TIME_ZONE,year:'numeric',month:'2-digit'}).formatToParts(d);const y=parts.find(x=>x.type==='year')?.value;const m=parts.find(x=>x.type==='month')?.value;return y&&m?\`${y}-\${m}\`:'';}catch{return '';}})).sort((a,b)=>a.label.localeCompare(b.label));\n  const completedOrPublic = safe.filter(p=>p.status==='CONCLUIDO' || p.acervo?.publicationState==='PUBLIC');\n  const rawThemes = buckets(completedOrPublic.flatMap(p=>(p.acervo?.palavrasChave||[]).map(clean).filter(Boolean)),15);\n  const rawWorkTypes = buckets(completedOrPublic.map(p=>WORK_TYPE_LABELS[p.acervo?.workType || 'NÃO INFORMADO'] || String(p.acervo?.workType || 'Não informado')));\n  const rawLocations = buckets(defendedItems.map(p=>clean(p.defesa?.local||'')).filter(Boolean),8);\n  const rawOutcomes = buckets(safe.map(p=>p.avaliacao?.resultadoLabel || p.avaliacao?.resultadoCode || '').filter(Boolean));\n  const rawFormats = buckets(safe.flatMap(p=>{const out:string[]=[];if(p.acervo?.publicFullWorkFileId)out.push('Trabalho completo');if(p.acervo?.publicExpandedAbstractFileId)out.push('Resumo expandido');return out;}));\n  const rawWeekdays = buckets(defendedItems.map(p=>datePart(p.defesa.startAt,{weekday:'long'})).map(label=>label?label.charAt(0).toUpperCase()+label.slice(1):'').filter(Boolean));\n  const rawDayparts = buckets(defendedItems.map(p=>{const hour=Number(datePart(p.defesa.startAt,{hour:'2-digit',hour12:false}).replace(/\\D/g,''));return hour<12?'Manhã':hour<18?'Tarde':'Noite';}));\n\n  const monthlyValues = rawMonths.map(item=>item.count);\n  const peak = [...rawMonths].sort((a,b)=>b.count-a.count)[0];\n  const completionDays = completedItems.map(p=>{const end=p.completedAt || '';const start=p.createdAt || '';if(!end||!start)return NaN;return Math.max(0,(new Date(end).getTime()-new Date(start).getTime())/86400000);}).filter(Number.isFinite);\n  const descriptive = !smallGroupSuppressed && monthlyValues.length ? {\n    monthlyMean:round1(mean(monthlyValues)), monthlyMedian:round1(median(monthlyValues)), monthlyStdDev:round1(stddev(monthlyValues)),\n    peakMonth:peak?.label||null, peakMonthCount:peak?.count||0, completionDaysMean:round1(mean(completionDays)), completionDaysMedian:round1(median(completionDays)), observedMonths:monthlyValues.length\n  } : null;\n\n  const detailedTotals = smallGroupSuppressed ? {completed:0,published:0,defended:0,inProgress:0,completionRate:0,publicationRate:0,coauthorRate:0} : {\n    completed,published,defended,inProgress:Math.max(0,total-completed),completionRate:total?round1(completed/total*100):0,publicationRate:total?round1(published/total*100):0,coauthorRate:total?round1(coauthors/total*100):0\n  };\n  const visible = (items:PublicIndicatorBucket[]) => smallGroupSuppressed ? [] : publicBuckets(items);\n  return {\n    generatedAt:new Date(now).toISOString(),\n    privacy:{containsPersonalData:false,smallGroupSuppressed,minimumGroupSize:MIN_PUBLIC_GROUP_SIZE,minimumBucketSize:MIN_PUBLIC_BUCKET_SIZE},\n    totals:{registered:total,...detailedTotals}, descriptive,\n    byStatus:smallGroupSuppressed?[]:rawByStatus.filter(item=>item.count>=MIN_PUBLIC_BUCKET_SIZE),\n    years:visible(rawYears), months:visible(rawMonths), themes:visible(rawThemes), workTypes:visible(rawWorkTypes), locations:visible(rawLocations), outcomes:visible(rawOutcomes),\n    formats:visible(rawFormats), weekdays:visible(rawWeekdays), dayparts:visible(rawDayparts)\n  };\n}\n`);

// 8) Página de Indicadores refeita com contrato defensivo: nenhum array ausente derruba a rota.
write('src/pages/IndicadoresPage.tsx', `import React, { useEffect, useMemo, useState } from 'react';\nimport { BarChart3, BookOpen, CalendarDays, CheckCircle2, Clock3, FileText, Gauge, MapPin, ShieldCheck, Tags, TrendingUp, Users2 } from 'lucide-react';\nimport { PortalSectionDivider } from '../components/PortalSectionDivider';\n\ntype Bucket = { label:string; count:number; key?:string };\ntype Indicators = {\n  generatedAt:string; privacy:{containsPersonalData:boolean;smallGroupSuppressed:boolean;minimumGroupSize:number;minimumBucketSize:number};\n  totals:{registered:number;completed:number;published:number;defended:number;inProgress:number;completionRate:number;publicationRate:number;coauthorRate:number};\n  descriptive:null|{monthlyMean:number;monthlyMedian:number;monthlyStdDev:number;peakMonth:string|null;peakMonthCount:number;completionDaysMean:number;completionDaysMedian:number;observedMonths:number};\n  byStatus:Bucket[];years:Bucket[];months:Bucket[];themes:Bucket[];workTypes:Bucket[];locations:Bucket[];outcomes:Bucket[];formats:Bucket[];weekdays:Bucket[];dayparts:Bucket[];\n};\nconst EMPTY:Indicators={generatedAt:'',privacy:{containsPersonalData:false,smallGroupSuppressed:false,minimumGroupSize:5,minimumBucketSize:3},totals:{registered:0,completed:0,published:0,defended:0,inProgress:0,completionRate:0,publicationRate:0,coauthorRate:0},descriptive:null,byStatus:[],years:[],months:[],themes:[],workTypes:[],locations:[],outcomes:[],formats:[],weekdays:[],dayparts:[]};\nconst safePayload=(raw:any):Indicators=>({...EMPTY,...raw,privacy:{...EMPTY.privacy,...(raw?.privacy||{})},totals:{...EMPTY.totals,...(raw?.totals||{})},descriptive:raw?.descriptive||null,byStatus:Array.isArray(raw?.byStatus)?raw.byStatus:[],years:Array.isArray(raw?.years)?raw.years:[],months:Array.isArray(raw?.months)?raw.months:[],themes:Array.isArray(raw?.themes)?raw.themes:[],workTypes:Array.isArray(raw?.workTypes)?raw.workTypes:[],locations:Array.isArray(raw?.locations)?raw.locations:[],outcomes:Array.isArray(raw?.outcomes)?raw.outcomes:[],formats:Array.isArray(raw?.formats)?raw.formats:[],weekdays:Array.isArray(raw?.weekdays)?raw.weekdays:[],dayparts:Array.isArray(raw?.dayparts)?raw.dayparts:[]});\nconst panel='h-full rounded-2xl border border-slate-300 bg-[#d5dce0] p-4 shadow-sm';\nconst pct=(n:number,d:number)=>d>0?Math.round(n/d*100):0;\nconst num=(n:number,digits=1)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:digits}).format(Number.isFinite(n)?n:0);\nconst monthLabel=(value?:string|null)=>{if(!value)return '—';const m=value.match(/(20\\d{2})[-/](\\d{1,2})/);if(!m)return value;return new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric'}).format(new Date(Number(m[1]),Number(m[2])-1,1)).replace('.','');};\n\nconst BarList:React.FC<{items?:Bucket[];percentage?:boolean;empty?:string}>=({items=[],percentage=false,empty='Sem volume suficiente.'})=>{const safe=Array.isArray(items)?items:[];if(!safe.length)return <div className=\"rounded-xl border border-dashed border-slate-300 bg-white p-6 text-center text-xs text-slate-500\">{empty}</div>;const max=Math.max(1,...safe.map(i=>i.count));const total=safe.reduce((s,i)=>s+i.count,0);return <div className=\"space-y-2\">{safe.map(item=><div key={\`${item.key||item.label}-${item.label}\`} className=\"grid grid-cols-[minmax(96px,170px)_1fr_58px] items-center gap-2 text-[11px]\"><span className=\"truncate font-bold text-slate-900\" title={item.label}>{item.label}</span><div className=\"h-5 overflow-hidden rounded-md border border-slate-300 bg-white\"><div className=\"h-full rounded-md bg-[#337959]\" style={{width:\`${Math.max(3,item.count/max*100)}%\`}}/></div><strong className=\"text-right text-black\">{percentage&&total?\`${pct(item.count,total)}%\`:item.count}</strong></div>)}</div>;};\nconst Trend:React.FC<{items?:Bucket[]}>=({items=[]})=>{const safe=Array.isArray(items)?items:[];if(safe.length<2)return <BarList items={safe}/>;const width=760,height=210,pad=28,max=Math.max(1,...safe.map(i=>i.count));const points=safe.map((item,index)=>({x:pad+index/(safe.length-1)*(width-pad*2),y:height-pad-item.count/max*(height-pad*2),item}));const path=points.map((p,i)=>\`${i?'L':'M'} ${p.x} ${p.y}\`).join(' ');return <div className=\"overflow-x-auto\"><svg viewBox={\`0 0 ${width} ${height}\`} className=\"h-[230px] min-w-[620px] w-full\" role=\"img\" aria-label=\"Tendência mensal de defesas\"><path d={path} fill=\"none\" stroke=\"#337959\" strokeWidth=\"4\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/>{points.map(({x,y,item})=><g key={item.label}><circle cx={x} cy={y} r=\"5\" fill=\"#fff\" stroke=\"#337959\" strokeWidth=\"3\"/><text x={x} y={Math.max(13,y-10)} textAnchor=\"middle\" fontSize=\"10\" fontWeight=\"800\" fill=\"#000\">{item.count}</text></g>)}</svg><div className=\"grid min-w-[620px] gap-1 text-[9px] text-slate-700\" style={{gridTemplateColumns:\`repeat(${safe.length},minmax(0,1fr))\`}}>{safe.map(i=><span key={i.label} className=\"truncate text-center\">{monthLabel(i.label)}</span>)}</div></div>;};\n\nexport const IndicadoresPage:React.FC=()=>{const[data,setData]=useState<Indicators|null>(null);const[loading,setLoading]=useState(true);const[error,setError]=useState('');useEffect(()=>{const controller=new AbortController();fetch('/api/public/indicators',{headers:{Accept:'application/json'},signal:controller.signal}).then(async r=>{if(!r.ok)throw new Error('Não foi possível carregar os indicadores.');return r.json();}).then(raw=>setData(safePayload(raw))).catch(err=>{if(err?.name!=='AbortError')setError(err instanceof Error?err.message:'Indicadores indisponíveis.');}).finally(()=>setLoading(false));return()=>controller.abort();},[]);const analytics=useMemo(()=>{if(!data)return null;const t=data.totals,d=data.descriptive,latest=data.months.at(-1),previous=data.months.at(-2);return{defenseRate:pct(t.defended,t.registered),defenseToCompletion:pct(t.completed,t.defended),completionToPublication:pct(t.published,t.completed),inProgressRate:pct(t.inProgress,t.registered),monthlyCv:d&&d.monthlyMean>0?Math.round(d.monthlyStdDev/d.monthlyMean*100):0,monthOverMonth:latest&&previous&&previous.count>0?Math.round((latest.count-previous.count)/previous.count*100):null,latestMonth:latest?.label||'—'};},[data]);return <div id=\"indicadores-publicos-page\" className=\"mx-auto max-w-none\"><section className=\"portal-public-header rounded-t-2xl border border-emerald-900/80 bg-[#005830] px-4 py-3 text-white shadow-sm\"><div className=\"flex items-center gap-2\"><BarChart3 className=\"h-5 w-5\"/><h1 className=\"text-base font-black uppercase tracking-tight\">Indicadores</h1></div></section><PortalSectionDivider/>{loading&&<div className={panel}>Carregando estatísticas acadêmicas…</div>}{error&&<div role=\"alert\" className=\"rounded-xl border border-rose-200 bg-rose-50 p-4 text-xs font-semibold text-rose-900\">{error}</div>}{data?.privacy.smallGroupSuppressed&&<div className=\"flex gap-2 rounded-xl border border-amber-300 bg-amber-50 p-4 text-xs text-amber-950\"><ShieldCheck className=\"h-4 w-4 shrink-0\"/><span>Proteção de grupos pequenos ativa. As distribuições permanecem ocultas até o volume mínimo de {data.privacy.minimumGroupSize} TCCs.</span></div>}{data&&!data.privacy.smallGroupSuppressed&&analytics&&<div className=\"space-y-3\"><section className=\"grid gap-2 sm:grid-cols-2 xl:grid-cols-4\">{[[FileText,'TCCs cadastrados',data.totals.registered,'base registrada'],[CheckCircle2,'Defesas realizadas',data.totals.defended,\`${analytics.defenseRate}% dos cadastrados\`],[TrendingUp,'TCCs concluídos',data.totals.completed,\`${data.totals.completionRate}% dos cadastrados\`],[BookOpen,'Publicações',data.totals.published,\`${data.totals.publicationRate}% dos cadastrados\`]].map(([Icon,label,value,detail]:any)=><article key={label} className={panel}><div className=\"flex items-start justify-between\"><div><div className=\"text-3xl font-black text-[#337959]\">{value}</div><h2 className=\"mt-1 text-xs font-black uppercase text-black\">{label}</h2></div><Icon className=\"h-5 w-5 text-[#337959]\"/></div><p className=\"mt-2 text-[11px] text-slate-700\">{detail}</p></article>)}</section><section className=\"grid gap-2 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8\">{[[Gauge,'Taxa de defesa',\`${analytics.defenseRate}%\`,'cadastrado → defendido'],[TrendingUp,'Defesa → conclusão',\`${analytics.defenseToCompletion}%\`,'conversão agregada'],[BookOpen,'Conclusão → publicação',\`${analytics.completionToPublication}%\`,'conversão agregada'],[Clock3,'Em andamento',\`${analytics.inProgressRate}%\`,\`${data.totals.inProgress} processos\`],[BarChart3,'Volatilidade mensal',\`${analytics.monthlyCv}%\`,'coeficiente de variação'],[CalendarDays,'Mês de pico',data.descriptive?monthLabel(data.descriptive.peakMonth):'—',data.descriptive?\`${data.descriptive.peakMonthCount} defesas\`:'sem série'],[Users2,'Coautoria',\`${data.totals.coauthorRate}%\`,'da base'],[TrendingUp,'Último mês',analytics.monthOverMonth===null?'—':\`${analytics.monthOverMonth>=0?'+':''}${analytics.monthOverMonth}%\`,monthLabel(analytics.latestMonth)]].map(([Icon,label,value,detail]:any)=><article key={label} className=\"rounded-xl border border-slate-300 bg-white p-3 shadow-sm\"><Icon className=\"h-4 w-4 text-[#337959]\"/><strong className=\"mt-2 block text-xl text-black\">{value}</strong><h3 className=\"text-[9px] font-black uppercase text-black\">{label}</h3><p className=\"mt-1 text-[9px] text-slate-600\">{detail}</p></article>)}</section><section className=\"grid gap-3 xl:grid-cols-[1.7fr_1fr]\"><article className={panel}><h2 className=\"text-xs font-black uppercase text-black\">Defesas por mês</h2><p className=\"mb-2 mt-1 text-[10px] text-slate-700\">Série temporal agregada dos períodos disponíveis.</p><Trend items={data.months}/></article><article className={panel}><h2 className=\"text-xs font-black uppercase text-black\">Situação dos processos</h2><p className=\"mb-3 mt-1 text-[10px] text-slate-700\">Distribuição atual por situação.</p><BarList items={data.byStatus} percentage/></article></section>{data.descriptive&&<section className=\"grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6\">{[['Média mensal',num(data.descriptive.monthlyMean)],['Mediana mensal',num(data.descriptive.monthlyMedian)],['Desvio-padrão',num(data.descriptive.monthlyStdDev)],['Mês de pico',monthLabel(data.descriptive.peakMonth)],['Tempo médio',data.descriptive.completionDaysMean?\`${num(data.descriptive.completionDaysMean)} dias\`:'—'],['Meses observados',data.descriptive.observedMonths]].map(([label,value])=><article key={String(label)} className=\"rounded-xl border border-slate-300 bg-white p-3\"><div className=\"text-lg font-black text-black\">{value}</div><div className=\"text-[9px] font-black uppercase text-slate-600\">{label}</div></article>)}</section>}<section className=\"grid gap-3 xl:grid-cols-3\"><article className={panel}><h2 className=\"mb-3 text-xs font-black uppercase text-black\">Evolução anual</h2><BarList items={data.years}/></article><article className={panel}><h2 className=\"mb-3 text-xs font-black uppercase text-black\">Dias da semana</h2><BarList items={data.weekdays}/></article><article className={panel}><h2 className=\"mb-3 text-xs font-black uppercase text-black\">Faixa de horário</h2><BarList items={data.dayparts}/></article></section><section className=\"grid gap-3 md:grid-cols-2 xl:grid-cols-4\"><article className={panel}><div className=\"mb-3 flex items-center gap-2\"><Tags className=\"h-4 w-4 text-[#337959]\"/><h2 className=\"text-xs font-black uppercase text-black\">Temas</h2></div><BarList items={data.themes}/></article><article className={panel}><div className=\"mb-3 flex items-center gap-2\"><FileText className=\"h-4 w-4 text-[#337959]\"/><h2 className=\"text-xs font-black uppercase text-black\">Tipos de trabalho</h2></div><BarList items={data.workTypes}/></article><article className={panel}><div className=\"mb-3 flex items-center gap-2\"><MapPin className=\"h-4 w-4 text-[#337959]\"/><h2 className=\"text-xs font-black uppercase text-black\">Locais</h2></div><BarList items={data.locations}/></article><article className={panel}><div className=\"mb-3 flex items-center gap-2\"><BookOpen className=\"h-4 w-4 text-[#337959]\"/><h2 className=\"text-xs font-black uppercase text-black\">Formatos publicados</h2></div><BarList items={data.formats}/></article></section><section className=\"grid gap-3 md:grid-cols-2\"><article className={panel}><h2 className=\"mb-3 text-xs font-black uppercase text-black\">Resultados</h2><BarList items={data.outcomes}/></article><article className={panel}><h2 className=\"mb-3 text-xs font-black uppercase text-black\">Nota metodológica</h2><p className=\"text-[11px] leading-5 text-slate-700\">Painel calculado somente com dados públicos agregados. Categorias com poucos registros são suprimidas automaticamente. Atualizado em {data.generatedAt?new Date(data.generatedAt).toLocaleString('pt-BR'):'—'}.</p></article></section></div>}</div>;};\n`);

// 9) Shell canônico dos workspaces de Configurações.
write('src/components/SettingsWorkspaceModal.tsx', `import React, { useEffect, useMemo, useState } from 'react';\nimport { X } from 'lucide-react';\n\nexport interface SettingsWorkspaceSection { id:string; label:string; description?:string; icon?:React.ComponentType<{className?:string}>; content:React.ReactNode; }\ninterface Props { open:boolean; title:string; icon?:React.ComponentType<{className?:string}>; sections:SettingsWorkspaceSection[]; onClose:()=>void; }\n\nexport const SettingsWorkspaceModal:React.FC<Props>=({open,title,icon:TitleIcon,sections,onClose})=>{const first=sections[0]?.id||'';const[active,setActive]=useState(first);useEffect(()=>{if(open&&(!active||!sections.some(section=>section.id===active)))setActive(first);},[open,first,active,sections]);const current=useMemo(()=>sections.find(section=>section.id===active)||sections[0],[sections,active]);if(!open||!current)return null;const CurrentIcon=current.icon;return <div className=\"fixed inset-0 z-[1000005] flex items-center justify-center bg-slate-950/65 p-3 backdrop-blur-sm\" onMouseDown={event=>{if(event.currentTarget===event.target)onClose();}}><section role=\"dialog\" aria-modal=\"true\" aria-label={title} className=\"portal-settings-workspace flex max-h-[94vh] w-full max-w-[1600px] flex-col overflow-hidden rounded-2xl border border-slate-300 bg-[#e1e6e9] shadow-2xl\"><header className=\"portal-settings-workspace-header flex items-center justify-between border-b-[16px] border-white bg-[#005830] px-4 py-3 text-white\"><div className=\"flex min-w-0 items-center gap-2\">{TitleIcon&&<TitleIcon className=\"h-5 w-5 shrink-0\"/>}<h2 className=\"truncate text-sm font-black uppercase tracking-wide\">{title}</h2></div><button type=\"button\" onClick={onClose} className=\"inline-flex h-8 w-8 items-center justify-center rounded-lg border border-white bg-white text-black shadow-sm\" aria-label=\"Fechar\"><X className=\"h-4 w-4\"/></button></header><div className=\"flex min-h-0 flex-1 flex-col overflow-hidden md:flex-row\"><aside className=\"max-h-52 w-full shrink-0 overflow-y-auto border-b border-slate-300 bg-[#d5dce0] p-3 md:max-h-none md:w-64 md:border-b-0 md:border-r\"><div className=\"rounded-xl border border-slate-300 bg-white p-2 shadow-sm\"><div className=\"mb-2 border-b border-slate-200 px-2 pb-2 text-[10px] font-black uppercase tracking-wider text-slate-600\">Navegação</div><div className=\"space-y-1\">{sections.map(section=>{const Icon=section.icon;const selected=section.id===current.id;return <button key={section.id} type=\"button\" onClick={()=>setActive(section.id)} className={\`flex w-full items-start gap-2 rounded-lg border px-2.5 py-2 text-left transition-colors ${selected?'border-[#337959] bg-[#337959] text-white':'border-transparent bg-white text-slate-800 hover:border-slate-300'}\`}>{Icon&&<Icon className=\"mt-0.5 h-4 w-4 shrink-0\"/>}<span className=\"min-w-0\"><strong className=\"block text-[11px] font-black uppercase\">{section.label}</strong>{section.description&&<span className={\`mt-0.5 block text-[9px] leading-4 ${selected?'text-white/80':'text-slate-500'}\`}>{section.description}</span>}</span></button>;})}</div></div></aside><main className=\"min-w-0 flex-1 overflow-y-auto bg-[#e1e6e9] p-3 sm:p-4\"><div className=\"mb-3 flex items-center gap-2 rounded-xl border border-[#286a4d] bg-[#337959] px-4 py-2.5 text-white shadow-sm\">{CurrentIcon&&<CurrentIcon className=\"h-4 w-4\"/>}<div><h3 className=\"text-xs font-black uppercase tracking-wide\">{current.label}</h3>{current.description&&<p className=\"mt-0.5 text-[10px] text-white/80\">{current.description}</p>}</div></div><div className=\"portal-settings-workspace-content min-w-0\">{current.content}</div></main></div></section></div>;};\n`);

// 10) Configurações: seis barras compactas, cada uma abre workspace consistente.
{
  const path = 'src/pages/ConfiguracoesPage.tsx';
  let source = read(path);
  source = replaceOnce(source, "import { AstenLogsPage } from './AstenLogsPage';", "import { AstenLogsPage } from './AstenLogsPage';\nimport { SettingsWorkspaceModal } from '../components/SettingsWorkspaceModal';", 'import do workspace');
  source = replaceRegex(
    source,
    /          <section id="portal-settings-hub" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">[\s\S]*?          <\/section>/,
    `          <section id="portal-settings-hub" className="portal-settings-list space-y-2">\n            {[\n              { id: 'personalization', title: 'Personalização do Portal', text: 'Aparência, navegação, páginas, tabelas e pop-ups.', icon: Palette },\n              { id: 'sync', title: 'Sincronização', text: 'Rodapé, Asten, Google, Supabase, Vercel e demais integrações.', icon: Sliders },\n              { id: 'access', title: 'Acesso', text: 'Autorizações e pessoas com acesso ao Portal.', icon: Lock },\n              { id: 'models', title: 'Modelos e Variáveis', text: 'Documentos, e-mails, formulários, fluxos e variáveis.', icon: Layers },\n              { id: 'signatures', title: 'Registros de Assinatura', text: 'Fila, método, situação e histórico de assinatura.', icon: FileCheck2 },\n              { id: 'logs', title: 'Registro de Logs', text: 'Auditoria, histórico técnico e rastreabilidade.', icon: ClipboardList },\n            ].map(({ id, title, text, icon: Icon }) => (\n              <button key={id} type="button" onClick={() => id === 'personalization' ? setPersonalizationHubOpen(true) : setActiveSettingsPanel(id as any)} className="portal-settings-title-bar flex w-full items-center gap-3 rounded-xl border border-slate-300 bg-[#d5dce0] px-3.5 py-3 text-left shadow-sm">\n                <Icon className="h-5 w-5 shrink-0 text-[#337959]" />\n                <span className="min-w-0 flex-1"><strong className="block text-xs font-black uppercase tracking-wide text-black">{title}</strong><span className="mt-0.5 block text-[10px] text-slate-600">{text}</span></span>\n                <ChevronRight className="h-4 w-4 shrink-0 text-slate-600" />\n              </button>\n            ))}\n          </section>`,
    'seis barras de configurações',
  );
  const start = source.indexOf('          {activeSettingsPanel && (');
  const marker = '          )}\n        </>';
  const end = source.indexOf(marker, start);
  if (start < 0 || end < 0) throw new Error('Modal legado de configurações não encontrado');
  const newModal = `          {activeSettingsPanel && (\n            <SettingsWorkspaceModal\n              open\n              title={activeSettingsPanel === 'sync' ? 'Sincronização' : activeSettingsPanel === 'access' ? 'Acesso' : activeSettingsPanel === 'models' ? 'Modelos e Variáveis' : activeSettingsPanel === 'signatures' ? 'Registros de Assinatura' : 'Registro de Logs'}\n              icon={activeSettingsPanel === 'sync' ? Sliders : activeSettingsPanel === 'access' ? Lock : activeSettingsPanel === 'models' ? Layers : activeSettingsPanel === 'signatures' ? FileCheck2 : ClipboardList}\n              onClose={() => setActiveSettingsPanel(null)}\n              sections={\n                activeSettingsPanel === 'sync' ? [\n                  { id: 'identity', label: 'Rodapé e identidade', description: 'Responsáveis, contatos e identidade operacional.', icon: Building2, content: settings ? <section className="rounded-xl border border-slate-300 bg-[#d5dce0] p-3"><MasterAndPresidentConfigForm settings={settings} onSettingsUpdated={() => { void refreshAuth(); showNotification('Configurações atualizadas.'); }} showNotification={showNotification} /><CommissionIdentityPanel isMaster /></section> : null },\n                  { id: 'integrations', label: 'Integrações e plataformas', description: 'Asten, Google, Supabase, Vercel e serviços externos.', icon: Globe, content: <InfrastructureIntegrationsPanel isMaster /> },\n                ] : activeSettingsPanel === 'access' ? [\n                  { id: 'authorizations', label: 'Autorizações de acesso', description: 'Gerencie discentes e demais perfis autorizados.', icon: Lock, content: <AuthorizedStudentsPanel canManage /> },\n                ] : activeSettingsPanel === 'models' ? [\n                  { id: 'studio', label: 'Estúdio de modelos e variáveis', description: 'Edite documentos, e-mails, formulários, fluxos e variáveis em um único ambiente.', icon: Layers, content: <div id="portal-models-workspace" className="space-y-3"><MasterDocumentModelsPanel /><IntegrationStudioPanel actorEmail={userEmail || ''} initialStudio={settings?.integrationStudio} matrixColumns={matrixColumns} setMatrixColumns={setMatrixColumns} matrixRows={matrixRows} setMatrixRows={setMatrixRows} emailTemplates={emailTemplates} setEmailTemplates={setEmailTemplates} formTemplates={formTemplates} setFormTemplates={setFormTemplates} docTemplates={docTemplates} setDocTemplates={setDocTemplates} workflowStages={workflowStages} setWorkflowStages={setWorkflowStages} driveModelosFolderUrl={driveModelosFolderUrl} setDriveModelosFolderUrl={setDriveModelosFolderUrl} onConnectDrive={handleConnectGoogleDrive} onScanDrive={handleUpdateAllDocumentsAndFields} isScanningDrive={isUpdatingAllDocs} notify={showNotification} /></div> },\n                ] : activeSettingsPanel === 'signatures' ? [\n                  { id: 'signature-ledger', label: 'Registros de assinatura', description: 'Acompanhe os documentos enviados e assinados.', icon: FileCheck2, content: <AstenLogsPage /> },\n                ] : [\n                  { id: 'audit-ledger', label: 'Registro de logs', description: 'Auditoria e histórico técnico do Portal.', icon: ClipboardList, content: <AuditLogsPage /> },\n                ]\n              }\n            />\n          )}\n`;
  source = source.slice(0, start) + newModal + source.slice(end + '          )}\n'.length);
  write(path, source);
}

// 11) Estúdio: navegação lateral estável e cabeçalho interno verde mais claro.
{
  const path = 'src/components/IntegrationStudioPanel.tsx';
  let source = read(path);
  const oldStart = `  return (\n    <div className={\`portal-workspace portal-studio ${panelClass} mb-5 overflow-hidden\`}>\n      <div className="border-b border-slate-200 bg-slate-50 p-2">\n        <div className="flex items-center gap-2"><div className="grid flex-1 grid-cols-2 gap-1 sm:grid-cols-3 xl:grid-cols-5">\n          {tabs.map((tab) => {\n            const Icon = tab.icon;\n            return <button key={tab.id} type="button" onClick={() => setActiveTab(tab.id)} className={\`flex items-center justify-center gap-1.5 rounded-lg border px-2 py-2 text-[9.5px] font-black uppercase transition cursor-pointer ${activeTab === tab.id ? 'border-slate-800 bg-slate-800 text-white shadow-2xs' : 'border-transparent bg-transparent text-slate-600 hover:border-slate-300 hover:bg-white'}\`}><Icon className="h-3.5 w-3.5" />{tab.label}</button>;\n          })}\n          </div>\n          <div className="hidden text-right text-[9px] font-semibold text-slate-500 md:block">{isDirty ? (draftSavedAt ? \`Rascunho automático ${new Date(draftSavedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}\` : 'Salvando rascunho…') : (lastSavedAt ? \`Publicado ${new Date(lastSavedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}\` : 'Ainda não publicado')}</div>\n          <button type="button" onClick={() => void persistSnapshot(true)} disabled={isSaving} className="inline-flex min-h-8 items-center justify-center gap-1.5 rounded-lg border border-slate-300 bg-white px-3 py-1.5 text-[10px] font-black uppercase tracking-wide text-slate-800 shadow-sm disabled:opacity-50"><Save className="h-3.5 w-3.5" />{isSaving ? 'Publicando…' : 'Publicar'}</button>\n        </div>\n      </div>\n\n      <div className="bg-slate-50/40 p-3 sm:p-4">`;
  const newStart = `  return (\n    <div className={\`portal-workspace portal-studio ${panelClass} mb-5 overflow-hidden\`}>\n      <div className="portal-studio-heading flex flex-wrap items-center justify-between gap-2 border-b border-[#286a4d] bg-[#337959] px-3 py-2.5 text-white">\n        <div><h3 className="text-xs font-black uppercase tracking-wide">Editor de modelos e variáveis</h3><p className="mt-0.5 text-[9px] text-white/80">Selecione uma área na navegação lateral e trabalhe com o artefato no mesmo contexto.</p></div>\n        <div className="flex items-center gap-2"><div className="hidden text-right text-[9px] font-semibold text-white/80 md:block">{isDirty ? (draftSavedAt ? \`Rascunho automático ${new Date(draftSavedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}\` : 'Salvando rascunho…') : (lastSavedAt ? \`Publicado ${new Date(lastSavedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}\` : 'Ainda não publicado')}</div><button type="button" onClick={() => void persistSnapshot(true)} disabled={isSaving} className="inline-flex min-h-8 items-center justify-center gap-1.5 rounded-lg border border-white bg-white px-3 py-1.5 text-[10px] font-black uppercase tracking-wide text-black shadow-sm disabled:opacity-50"><Save className="h-3.5 w-3.5" />{isSaving ? 'Publicando…' : 'Publicar'}</button></div>\n      </div>\n      <div className="flex min-h-[68vh] flex-col md:flex-row">\n        <aside className="w-full shrink-0 border-b border-slate-300 bg-[#d5dce0] p-2 md:w-56 md:border-b-0 md:border-r">\n          <div className="rounded-xl border border-slate-300 bg-white p-2 shadow-sm"><div className="mb-2 border-b border-slate-200 px-2 pb-2 text-[9px] font-black uppercase tracking-wider text-slate-500">Modelos e variáveis</div><div className="space-y-1">{tabs.map(tab=>{const Icon=tab.icon;const selected=activeTab===tab.id;return <button key={tab.id} type="button" onClick={()=>setActiveTab(tab.id)} className={\`flex w-full items-center gap-2 rounded-lg border px-2.5 py-2 text-left text-[10px] font-black uppercase transition-colors ${selected?'border-[#337959] bg-[#337959] text-white':'border-transparent bg-white text-slate-700 hover:border-slate-300'}\`}><Icon className="h-3.5 w-3.5 shrink-0"/>{tab.label}</button>;})}</div></div>\n        </aside>\n        <div className="min-w-0 flex-1 bg-slate-50/40 p-3 sm:p-4">`;
  source = replaceOnce(source, oldStart, newStart, 'navegação lateral do Estúdio');
  // Fecha o contêiner flex adicional antes do root.
  const tail = `        )}\n      </div>\n    </div>\n  );\n};`;
  const newTail = `        )}\n        </div>\n      </div>\n    </div>\n  );\n};`;
  source = replaceOnce(source, tail, newTail, 'fechamento do Estúdio');
  // Pré-visualização real de documento quando há arquivo Drive utilizável.
  source = replaceOnce(
    source,
    `<div className="rounded-2xl border border-slate-300 bg-slate-100 p-5 sm:p-8"><div className="mx-auto flex min-h-[420px] max-w-[720px] flex-col items-center justify-center rounded-2xl border border-slate-200 bg-white p-8 text-center shadow-sm"><FileText className="mb-4 h-10 w-10 text-emerald-700"/><strong className="text-base text-slate-900">A aparência vem integralmente do DOCX oficial</strong><p className="mt-3 max-w-lg text-xs leading-6 text-slate-600">Para evitar perda de cabeçalhos, tabelas, assinaturas, margens ou paginação, o portal não reestiliza o modelo. Ele cria uma cópia temporária no Google Docs, substitui somente marcadores explícitos, exporta o PDF e preserva o arquivo original.</p><div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-[11px] font-semibold text-amber-950">Visualize e altere a diagramação diretamente no arquivo do Google Drive. Use este Estúdio para controlar dados, destinatários, regras e sequência.</div></div></div>`,
    `<div className="overflow-hidden rounded-2xl border border-slate-300 bg-slate-100"><div className="border-b border-slate-300 bg-white px-4 py-3"><div className="text-[10px] font-black uppercase text-slate-500">Pré-visualização do documento</div><div className="mt-1 truncate text-xs font-bold text-slate-900">{selectedDoc.label}</div></div>{selectedDoc.driveFileId && !selectedDoc.driveFileId.startsWith('tmpl-') ? <iframe title={\`Pré-visualização de ${selectedDoc.label}\`} src={\`https://drive.google.com/file/d/${selectedDoc.driveFileId}/preview\`} className="h-[680px] w-full border-0 bg-white" /> : <div className="mx-auto flex min-h-[420px] max-w-[720px] flex-col items-center justify-center p-8 text-center"><FileText className="mb-4 h-10 w-10 text-[#337959]"/><strong className="text-base text-slate-900">Vincule o DOCX oficial para visualizar</strong><p className="mt-3 max-w-lg text-xs leading-6 text-slate-600">O Portal preserva a diagramação original e substitui somente as variáveis reconhecidas. Assim que o arquivo oficial estiver vinculado ao Drive, a pré-visualização aparece aqui sem separar edição e conferência.</p></div>}</div>`,
    'pré-visualização de documentos',
  );
  write(path, source);
}

