write('server/version1046StructuralContract.test.ts', `import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {readFileSync} from 'node:fs';\nconst read=(p:string)=>readFileSync(new URL('../'+p,import.meta.url),'utf8');\ntest('release atual é 1.0.46',()=>{assert.equal(JSON.parse(read('package.json')).version,'1.0.46');});\ntest('cores de processo não são sobrescritas pela data fora da agenda pública',()=>{const runtime=read('src/components/PortalStructuralRuntime.tsx');assert.match(runtime,/if \(!table\.closest\('#formal-monthly-calendar-section'\)\) return/);assert.doesNotMatch(runtime,/fetch\('\/api\/processes'/);});\ntest('calendário classifica fim de semana no React e não espera busca paralela',()=>{const home=read('src/pages/HomePage.tsx');const runtime=read('src/components/PortalStructuralRuntime.tsx');assert.match(home,/isWeekend = colIndex === 0 \|\| colIndex === 6/);assert.match(home,/hasEvents && !isWeekend/);assert.match(runtime,/function enhanceCalendar\(\)/);assert.doesNotMatch(runtime,/async function enhanceCalendar/);});\ntest('indicadores compartilham contrato completo e defensivo',()=>{const api=read('server/publicIndicators.ts');const page=read('src/pages/IndicadoresPage.tsx');for(const key of ['coauthorRate','descriptive','formats','weekdays','dayparts'])assert.match(api,new RegExp(key));assert.match(page,/safePayload/);assert.match(page,/items=\[\]/);});\ntest('configurações usam seis barras e workspace modal padronizado',()=>{const config=read('src/pages/ConfiguracoesPage.tsx');const shell=read('src/components/SettingsWorkspaceModal.tsx');assert.match(config,/portal-settings-title-bar/);assert.doesNotMatch(config,/portal-settings-hub-card/);assert.match(shell,/bg-\[#005830\]/);assert.match(shell,/Navegação/);});\ntest('estúdio usa navegação lateral e pré-visualização de documento',()=>{const studio=read('src/components/IntegrationStudioPanel.tsx');assert.match(studio,/md:w-56/);assert.match(studio,/Pré-visualização do documento/);assert.match(studio,/drive\.google\.com\/file\/d/);});\ntest('tipografia tabular e paleta final são carregadas por último',()=>{const formatter=read('src/utils/tableFormatters.ts');const main=read('src/main.tsx');const css=read('src/portal-version-1046.css');assert.match(formatter,/cellTextColorClass = 'text-black'/);assert.ok(main.indexOf('portal-version-1046.css')>main.indexOf('portal-public-ux-1044.css'));assert.match(css,/portal-role-process-button/);});\n`);

